#include <queue>
#include <vector>
#include <iostream>

int main() {
    // Default: Max-Heap (uses std::less<int>)
    std::priority_queue<int> max_pq;
    max_pq.push(10); max_pq.push(20); max_pq.push(5);
    std::cout << "Max Top: " << max_pq.top() << " (Expected 20)\n";

    // Min-Heap configuration (uses std::greater<int>)
    // Note the necessity to specify the container when overriding Compare
    std::priority_queue<int, std::vector<int>, std::greater<int>> min_pq;
    min_pq.push(10); min_pq.push(20); min_pq.push(5);
    std::cout << "Min Top: " << min_pq.top() << " (Expected 5)\n";
}
